// Primary port — defined by the application
public interface PlaceOrderUseCase {
    OrderId placeOrder(PlaceOrderCommand command);
}

// Driving adapter — the HTTP layer calls this port
@RestController
public class PlaceOrderController {
    private final PlaceOrderUseCase useCase;

    public PlaceOrderController(PlaceOrderUseCase useCase) {
        this.useCase = useCase;
    }

    @PostMapping("/orders")
    public ResponseEntity<String> handle(@RequestBody PlaceOrderRequest req) {
        OrderId id = useCase.placeOrder(new PlaceOrderCommand(
            req.customerId(), req.items()
        ));
        return ResponseEntity.ok(id.value());
    }
}

