// Pure domain entity — no framework annotations, no external imports
public class Order {
    private final OrderId id;
    private final CustomerId customerId;
    private final List<OrderLine> lines;
    private OrderStatus status;

    public Order(OrderId id, CustomerId customerId, List<OrderLine> lines) {
        this.id = Objects.requireNonNull(id);
        this.customerId = Objects.requireNonNull(customerId);
        this.lines = List.copyOf(lines);
        this.status = OrderStatus.PENDING;
    }

    public void confirm() {
        if (status != OrderStatus.PENDING) {
            throw new OrderAlreadyProcessedException(id);
        }
        this.status = OrderStatus.CONFIRMED;
    }

    // getters only — no setters, no ORM lifecycle methods
}

// Application layer — implements the primary port
public class PlaceOrderService implements PlaceOrderUseCase {
    private final OrderRepository orders;       // secondary port
    private final EventPublisher events;        // secondary port

    @Override
    public OrderId placeOrder(PlaceOrderCommand cmd) {
        // 1. Construct domain object
        Order order = new Order(
            OrderId.generate(),
            cmd.customerId(),
            cmd.lines()
        );
        // 2. Execute domain logic
        order.confirm();
        // 3. Persist via secondary port
        orders.save(order);
        // 4. Publish event via secondary port
        events.publish(new OrderPlaced(order.id(), order.customerId()));
        return order.id();
    }
}

// In-memory stub for unit testing
public class InMemoryOrderRepository implements OrderRepository {
    private final Map<OrderId, Order> store = new HashMap<>();

    @Override
    public void save(Order order) { store.put(order.id(), order); }

    @Override
    public Optional<Order> findById(OrderId id) {
        return Optional.ofNullable(store.get(id));
    }
}

// Unit test — no Spring, no database, no test container
class PlaceOrderServiceTest {
    @Test
    void placingOrderPersistsItAndPublishesEvent() {
        var orders = new InMemoryOrderRepository();
        var events = new InMemoryEventPublisher();
        var service = new PlaceOrderService(orders, events);

        var id = service.placeOrder(new PlaceOrderCommand(
            new CustomerId("c1"), List.of(aLine())
        ));

        assertThat(orders.findById(id)).isPresent();
        assertThat(events.published()).hasSize(1)
            .first().isInstanceOf(OrderPlaced.class);
    }
}
